export const BOOK = {"id":"nawawi","title":"Les quarante hadiths","titleAr":"الأَرْبَعُونَ النَّوَوِيَّة","author":"Imam an-Nawawî (m. 676 H / 1277)","level":"Débutant","desc":"Les 42 hadiths qui résument les fondements de la religion : l’intention, l’islam, la foi, le bon caractère…","credit":"Texte arabe : paquet « nawawi-40-hadith-data » (CC BY 4.0). Traduction française et vocabulaire : Daaraji.","chapters":[{"id":"N01","num":1,"title":"Les actes ne valent que par les intentions","titleAr":"","takeaway":"Purifie ton intention : Allah regarde ce qu’il y a dans ton cœur.","source":"Rapporté par les deux imams du hadith, al-Bukhârî et Muslim, dans leurs Sahîh, les plus authentiques des livres.","units":[{"id":"N01","ar":"عَنْ أَمِيرِ الْمُؤْمِنِينَ أَبِي حَفْصٍ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ: «إنَّمَا الْأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى، فَمَنْ كَانَتْ هِجْرَتُهُ إلَى اللَّهِ وَرَسُولِهِ فَهِجْرَتُهُ إلَى اللَّهِ وَرَسُولِهِ، وَمَنْ كَانَتْ هِجْرَتُهُ لِدُنْيَا يُصِيبُهَا أَوْ امْرَأَةٍ يَنْكِحُهَا فَهِجْرَتُهُ إلَى مَا هَاجَرَ إلَيْهِ». رَوَاهُ إِمَامَا الْمُحَدِّثِينَ أَبُو عَبْدِ اللهِ مُحَمَّدُ بنُ إِسْمَاعِيل بن إِبْرَاهِيم بن الْمُغِيرَة بن بَرْدِزبَه الْبُخَارِيُّ الْجُعْفِيُّ رَضِيَ اللهُ عَنْهُمَا فِي «صَحِيحَيْهِمَا» اللذَينِ هُمَا أَصَحُّ الْكُتُبِ الْمُصَنَّفَةِ.","fr":"D’après le commandeur des croyants Abû Hafs ‘Umar ibn al-Khattâb (qu’Allah l’agrée), qui a dit : J’ai entendu le Messager d’Allah ﷺ dire : « Les actes ne valent que par les intentions, et chacun n’aura que ce qu’il a eu l’intention de faire. Celui dont l’émigration était pour Allah et Son Messager, son émigration est pour Allah et Son Messager ; celui dont l’émigration était pour un bien de ce monde qu’il voulait obtenir, ou pour une femme qu’il voulait épouser, son émigration est pour ce vers quoi il a émigré. »"}]},{"id":"N02","num":2,"title":"L’islam, la foi et l’excellence (hadith de Gabriel)","titleAr":"","takeaway":"La religion a trois degrés : l’islam, la foi (îmân) et l’excellence (ihsân).","source":"Rapporté par Muslim.","units":[{"id":"N02","ar":"عَنْ عُمَرَ رَضِيَ اللهُ عَنْهُ أَيْضًا قَالَ: «بَيْنَمَا نَحْنُ جُلُوسٌ عِنْدَ رَسُولِ اللَّهِ ﷺ ذَاتَ يَوْمٍ، إذْ طَلَعَ عَلَيْنَا رَجُلٌ شَدِيدُ بَيَاضِ الثِّيَابِ، شَدِيدُ سَوَادِ الشَّعْرِ، لَا يُرَى عَلَيْهِ أَثَرُ السَّفَرِ، وَلَا يَعْرِفُهُ مِنَّا أَحَدٌ. حَتَّى جَلَسَ إلَى النَّبِيِّ ﷺ. فَأَسْنَدَ رُكْبَتَيْهِ إلَى رُكْبَتَيْهِ، وَوَضَعَ كَفَّيْهِ عَلَى فَخِذَيْهِ، وَقَالَ: يَا مُحَمَّدُ أَخْبِرْنِي عَنْ الْإِسْلَامِ. فَقَالَ رَسُولُ اللَّهِ ﷺ الْإِسْلَامُ أَنْ تَشْهَدَ أَنْ لَا إلَهَ إلَّا اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَتُقِيمَ الصَّلَاةَ، وَتُؤْتِيَ الزَّكَاةَ، وَتَصُومَ رَمَضَانَ، وَتَحُجَّ الْبَيْتَ إنْ اسْتَطَعْت إلَيْهِ سَبِيلًا. قَالَ: صَدَقْت. فَعَجِبْنَا لَهُ يَسْأَلُهُ وَيُصَدِّقُهُ! قَالَ: فَأَخْبِرْنِي عَنْ الْإِيمَانِ. قَالَ: أَنْ تُؤْمِنَ بِاَللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ وَالْيَوْمِ الْآخِرِ، وَتُؤْمِنَ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ. قَالَ: صَدَقْت. قَالَ: فَأَخْبِرْنِي عَنْ الْإِحْسَانِ. قَالَ: أَنْ تَعْبُدَ اللَّهَ كَأَنَّك تَرَاهُ، فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاك. قَالَ: فَأَخْبِرْنِي عَنْ السَّاعَةِ. قَالَ: مَا الْمَسْئُولُ عَنْهَا بِأَعْلَمَ مِنْ السَّائِلِ. قَالَ: فَأَخْبِرْنِي عَنْ أَمَارَاتِهَا؟ قَالَ: أَنْ تَلِدَ الْأَمَةُ رَبَّتَهَا، وَأَنْ تَرَى الْحُفَاةَ الْعُرَاةَ الْعَالَةَ رِعَاءَ الشَّاءِ يَتَطَاوَلُونَ فِي الْبُنْيَانِ. ثُمَّ انْطَلَقَ، فَلَبِثْتُ مَلِيًّا، ثُمَّ قَالَ: يَا عُمَرُ أَتَدْرِي مَنْ السَّائِلُ؟. ‫‬قُلْتُ: اللَّهُ وَرَسُولُهُ أَعْلَمُ. قَالَ: فَإِنَّهُ جِبْرِيلُ أَتَاكُمْ يُعَلِّمُكُمْ دِينَكُمْ».","fr":"D’après ‘Umar (qu’Allah l’agrée) également : « Alors que nous étions assis un jour auprès du Messager d’Allah ﷺ, un homme apparut devant nous, aux vêtements d’une blancheur éclatante et aux cheveux d’un noir intense. On ne voyait sur lui aucune trace de voyage, et aucun de nous ne le connaissait. Il s’assit face au Prophète ﷺ, appuya ses genoux contre les siens, posa ses mains sur ses cuisses et dit : “Ô Muhammad, informe-moi sur l’islam.” Le Messager d’Allah ﷺ répondit : “L’islam, c’est que tu attestes qu’il n’y a de divinité qu’Allah et que Muhammad est le Messager d’Allah, que tu accomplisses la prière, que tu acquittes la zakât, que tu jeûnes le Ramadan et que tu fasses le pèlerinage à la Maison si tu en as les moyens.” Il dit : “Tu as dit vrai.” Nous nous étonnâmes qu’il l’interroge puis lui donne raison. Il dit : “Informe-moi sur la foi.” Il répondit : “C’est que tu croies en Allah, en Ses anges, en Ses livres, en Ses messagers, au Jour dernier, et que tu croies au destin, son bien et son mal.” Il dit : “Tu as dit vrai. Informe-moi sur l’excellence (ihsân).” Il répondit : “C’est que tu adores Allah comme si tu Le voyais ; et si tu ne Le vois pas, Lui te voit.” Il dit : “Informe-moi sur l’Heure.” Il répondit : “Celui qui est interrogé n’en sait pas plus que celui qui interroge.” Il dit : “Informe-moi sur ses signes.” Il répondit : “Que la servante enfante sa maîtresse, et que tu voies les va-nu-pieds, nus, pauvres, bergers de moutons, rivaliser dans la hauteur des constructions.” Puis il s’en alla. Je restai un moment, puis il me dit : “Ô ‘Umar, sais-tu qui était celui qui interrogeait ?” Je dis : “Allah et Son Messager savent mieux.” Il dit : “C’était Gabriel, venu vous enseigner votre religion.” »"}]},{"id":"N03","num":3,"title":"Les cinq piliers de l’islam","titleAr":"","takeaway":"L’islam repose sur cinq piliers : l’attestation, la prière, la zakât, le pèlerinage et le jeûne.","source":"Rapporté par al-Bukhârî et Muslim.","units":[{"id":"N03","ar":"عَنْ أَبِي عَبْدِ الرَّحْمَنِ عَبْدِ اللَّهِ بْنِ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: سَمِعْت رَسُولَ اللَّهِ ﷺ يَقُولُ: «بُنِيَ الْإِسْلَامُ عَلَى خَمْسٍ: شَهَادَةِ أَنْ لَا إلَهَ إلَّا اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَإِقَامِ الصَّلَاةِ، وَإِيتَاءِ الزَّكَاةِ، وَحَجِّ الْبَيْتِ، وَصَوْمِ رَمَضَانَ».","fr":"D’après Abû ‘Abd ar-Rahmân ‘Abd Allâh, fils de ‘Umar ibn al-Khattâb (qu’Allah les agrée), qui a dit : J’ai entendu le Messager d’Allah ﷺ dire : « L’islam est bâti sur cinq piliers : l’attestation qu’il n’y a de divinité qu’Allah et que Muhammad est le Messager d’Allah, l’accomplissement de la prière, l’acquittement de la zakât, le pèlerinage à la Maison et le jeûne de Ramadan. »"}]},{"id":"N04","num":4,"title":"La création de l’homme et le destin","titleAr":"","takeaway":"Les actes valent par leur fin : demande à Allah une bonne fin.","source":"Rapporté par al-Bukhârî et Muslim.","units":[{"id":"N04","ar":"عَنْ أَبِي عَبْدِ الرَّحْمَنِ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: حَدَّثَنَا رَسُولُ اللَّهِ ﷺ -وَهُوَ الصَّادِقُ الْمَصْدُوقُ-: «إنَّ أَحَدَكُمْ يُجْمَعُ خَلْقُهُ فِي بَطْنِ أُمِّهِ أَرْبَعِينَ يَوْمًا نُطْفَةً، ثُمَّ يَكُونُ عَلَقَةً مِثْلَ ذَلِكَ، ثُمَّ يَكُونُ مُضْغَةً مِثْلَ ذَلِكَ، ثُمَّ يُرْسَلُ إلَيْهِ الْمَلَكُ فَيَنْفُخُ فِيهِ الرُّوحَ، وَيُؤْمَرُ بِأَرْبَعِ كَلِمَاتٍ: بِكَتْبِ رِزْقِهِ، وَأَجَلِهِ، وَعَمَلِهِ، وَشَقِيٍّ أَمْ سَعِيدٍ؛ فَوَاَللَّهِ الَّذِي لَا إلَهَ غَيْرُهُ إنَّ أَحَدَكُمْ لَيَعْمَلُ بِعَمَلِ أَهْلِ الْجَنَّةِ حَتَّى مَا يَكُونُ بَيْنَهُ وَبَيْنَهَا إلَّا ذِرَاعٌ فَيَسْبِقُ عَلَيْهِ الْكِتَابُ فَيَعْمَلُ بِعَمَلِ أَهْلِ النَّارِ فَيَدْخُلُهَا. وَإِنَّ أَحَدَكُمْ لَيَعْمَلُ بِعَمَلِ أَهْلِ النَّارِ حَتَّى مَا يَكُونُ بَيْنَهُ وَبَيْنَهَا إلَّا ذِرَاعٌ فَيَسْبِقُ عَلَيْهِ الْكِتَابُ فَيَعْمَلُ بِعَمَلِ أَهْلِ الْجَنَّةِ فَيَدْخُلُهَا».","fr":"D’après Abû ‘Abd ar-Rahmân ‘Abd Allâh ibn Mas‘ûd (qu’Allah l’agrée), qui a dit : Le Messager d’Allah ﷺ — le véridique, dont la véracité est confirmée — nous a rapporté : « La création de chacun de vous est réunie dans le ventre de sa mère pendant quarante jours sous forme de goutte, puis il devient une adhérence pendant une durée semblable, puis un morceau de chair pendant une durée semblable. Puis l’ange lui est envoyé : il insuffle en lui l’esprit et reçoit l’ordre d’écrire quatre choses : sa subsistance, son terme, ses œuvres, et s’il sera malheureux ou heureux. Par Allah, en dehors de qui il n’y a pas de divinité : l’un de vous accomplit les œuvres des gens du Paradis jusqu’à ce qu’il n’y ait plus entre lui et le Paradis qu’une coudée ; alors ce qui est écrit le devance, il accomplit les œuvres des gens de l’Enfer et y entre. Et l’un de vous accomplit les œuvres des gens de l’Enfer jusqu’à ce qu’il n’y ait plus entre lui et l’Enfer qu’une coudée ; alors ce qui est écrit le devance, il accomplit les œuvres des gens du Paradis et y entre. »"}]},{"id":"N05","num":5,"title":"Le rejet des innovations","titleAr":"","takeaway":"Un acte n’est accepté que s’il est sincère et conforme à la sunna.","source":"Rapporté par al-Bukhârî et Muslim.","units":[{"id":"N05","ar":"عَنْ أُمِّ الْمُؤْمِنِينَ أُمِّ عَبْدِ اللَّهِ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا، قَالَتْ: قَالَ: رَسُولُ اللَّهِ ﷺ «مَنْ أَحْدَثَ فِي أَمْرِنَا هَذَا مَا لَيْسَ مِنْهُ فَهُوَ رَدٌّ وَفِي رِوَايَةٍ لِمُسْلِمٍ: مَنْ عَمِلَ عَمَلًا لَيْسَ عَلَيْهِ أَمْرُنَا فَهُوَ رَدٌّ».","fr":"D’après la mère des croyants, Umm ‘Abd Allâh ‘Âïcha (qu’Allah l’agrée), qui a dit : Le Messager d’Allah ﷺ a dit : « Celui qui introduit dans notre affaire (notre religion) ce qui n’en fait pas partie, cela est rejeté. » Et dans une version de Muslim : « Celui qui accomplit un acte qui n’est pas conforme à notre affaire, cet acte est rejeté. »"}]},{"id":"N06","num":6,"title":"Le licite et l’illicite sont clairs","titleAr":"","takeaway":"Évite le douteux et soigne ton cœur : tout le corps en dépend.","source":"Rapporté par al-Bukhârî et Muslim.","units":[{"id":"N06","ar":"عَنْ أَبِي عَبْدِ اللَّهِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللَّهُ عَنْهُمَا، قَالَ: سَمِعْت رَسُولَ اللَّهِ ﷺ يَقُولُ: «إنَّ الْحَلَالَ بَيِّنٌ، وَإِنَّ الْحَرَامَ بَيِّنٌ، وَبَيْنَهُمَا أُمُورٌ مُشْتَبِهَاتٌ لَا يَعْلَمُهُنَّ كَثِيرٌ مِنْ النَّاسِ، فَمَنْ اتَّقَى الشُّبُهَاتِ فَقْد اسْتَبْرَأَ لِدِينِهِ وَعِرْضِهِ، وَمَنْ وَقَعَ فِي الشُّبُهَاتِ وَقَعَ فِي الْحَرَامِ، كَالرَّاعِي يَرْعَى حَوْلَ الْحِمَى يُوشِكُ أَنْ يَرْتَعَ فِيهِ، أَلَا وَإِنَّ لِكُلِّ مَلِكٍ حِمًى، أَلَا وَإِنَّ حِمَى اللَّهِ مَحَارِمُهُ، أَلَا وَإِنَّ فِي الْجَسَدِ مُضْغَةً إذَا صَلَحَتْ صَلَحَ الْجَسَدُ كُلُّهُ، وَإذَا فَسَدَتْ فَسَدَ الْجَسَدُ كُلُّهُ، أَلَا وَهِيَ الْقَلْبُ».","fr":"D’après Abû ‘Abd Allâh an-Nu‘mân ibn Bachîr (qu’Allah les agrée), qui a dit : J’ai entendu le Messager d’Allah ﷺ dire : « Le licite est clair et l’illicite est clair, et entre les deux il y a des choses ambiguës que beaucoup de gens ne connaissent pas. Celui qui se garde des choses ambiguës préserve sa religion et son honneur ; et celui qui tombe dans les choses ambiguës tombe dans l’illicite, comme le berger qui fait paître autour d’un domaine protégé et risque d’y pénétrer. Certes, chaque roi a un domaine protégé, et le domaine protégé d’Allah, ce sont Ses interdits. Certes, il y a dans le corps un morceau de chair : s’il est sain, tout le corps est sain ; s’il est corrompu, tout le corps est corrompu. Certes, c’est le cœur. »"}]},{"id":"N07","num":7,"title":"La religion est le bon conseil","titleAr":"","takeaway":"La religion, c’est la sincérité envers Allah, Son Livre, Son Messager, les dirigeants et tous les musulmans.","source":"Rapporté par Muslim.","units":[{"id":"N07","ar":"عَنْ أَبِي رُقَيَّةَ تَمِيمِ بْنِ أَوْسٍ الدَّارِيِّ رَضِيَ اللهُ عَنْهُ أَنَّ النَّبِيَّ ﷺ قَالَ: «الدِّينُ النَّصِيحَةُ.» قُلْنَا: لِمَنْ؟ قَالَ: «لِلَّهِ، وَلِكِتَابِهِ، وَلِرَسُولِهِ، وَلِأَئِمَّةِ الْمُسْلِمِينَ وَعَامَّتِهِمْ.».","fr":"D’après Abû Ruqayya Tamîm ibn Aws ad-Dârî (qu’Allah l’agrée) : Le Prophète ﷺ a dit : « La religion est le bon conseil (la sincérité). » Nous demandâmes : « Envers qui ? » Il dit : « Envers Allah, Son Livre, Son Messager, les dirigeants des musulmans et l’ensemble des musulmans. »"}]},{"id":"N08","num":8,"title":"Le caractère sacré du musulman","titleAr":"","takeaway":"Celui qui entre dans l’islam voit son sang et ses biens protégés.","source":"Rapporté par al-Bukhârî et Muslim.","units":[{"id":"N08","ar":"عَنْ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا، أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَشْهَدُوا أَنْ لَا إلَهَ إلَّا اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَيُقِيمُوا الصَّلَاةَ، وَيُؤْتُوا الزَّكَاةَ؛ فَإِذَا فَعَلُوا ذَلِكَ عَصَمُوا مِنِّي دِمَاءَهُمْ وَأَمْوَالَهُمْ إلَّا بِحَقِّ الْإِسْلَامِ، وَحِسَابُهُمْ عَلَى اللَّهِ تَعَالَى».","fr":"D’après Ibn ‘Umar (qu’Allah les agrée) : Le Messager d’Allah ﷺ a dit : « J’ai reçu l’ordre de combattre les gens jusqu’à ce qu’ils attestent qu’il n’y a de divinité qu’Allah et que Muhammad est le Messager d’Allah, qu’ils accomplissent la prière et acquittent la zakât. S’ils le font, ils protègent de moi leur sang et leurs biens, sauf par le droit de l’islam, et leur compte appartient à Allah le Très-Haut. »"}]},{"id":"N09","num":9,"title":"Faites ce que vous pouvez","titleAr":"","takeaway":"Évite tout l’interdit ; accomplis l’ordonné selon tes moyens.","source":"Rapporté par al-Bukhârî et Muslim.","units":[{"id":"N09","ar":"عَنْ أَبِي هُرَيْرَةَ عَبْدِ الرَّحْمَنِ بْنِ صَخْرٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْت رَسُولَ اللَّهِ ﷺ يَقُولُ: «مَا نَهَيْتُكُمْ عَنْهُ فَاجْتَنِبُوهُ، وَمَا أَمَرْتُكُمْ بِهِ فَأْتُوا مِنْهُ مَا اسْتَطَعْتُمْ، فَإِنَّمَا أَهْلَكَ الَّذِينَ مِنْ قَبْلِكُمْ كَثْرَةُ مَسَائِلِهِمْ وَاخْتِلَافُهُمْ عَلَى أَنْبِيَائِهِمْ».","fr":"D’après Abû Hurayra ‘Abd ar-Rahmân ibn Sakhr (qu’Allah l’agrée), qui a dit : J’ai entendu le Messager d’Allah ﷺ dire : « Ce que je vous ai interdit, évitez-le ; ce que je vous ai ordonné, faites-en ce que vous pouvez. Ceux qui vous ont précédés n’ont été anéantis que par leurs nombreuses questions et leurs désaccords avec leurs prophètes. »"}]},{"id":"N10","num":10,"title":"Ne manger que ce qui est licite","titleAr":"","takeaway":"Le licite est une condition pour que les invocations soient exaucées.","source":"Rapporté par Muslim.","units":[{"id":"N10","ar":"عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ «إنَّ اللَّهَ طَيِّبٌ لَا يَقْبَلُ إلَّا طَيِّبًا، وَإِنَّ اللَّهَ أَمَرَ الْمُؤْمِنِينَ بِمَا أَمَرَ بِهِ الْمُرْسَلِينَ فَقَالَ تَعَالَى:»يَا أَيُّهَا الرُّسُلُ كُلُوا مِنْ الطَّيِّبَاتِ وَاعْمَلُوا صَالِحًا«، وَقَالَ تَعَالَى:»يَا أَيُّهَا الَّذِينَ آمَنُوا كُلُوا مِنْ طَيِّبَاتِ مَا رَزَقْنَاكُمْ«ثُمَّ ذَكَرَ الرَّجُلَ يُطِيلُ السَّفَرَ أَشْعَثَ أَغْبَرَ يَمُدُّ يَدَيْهِ إلَى السَّمَاءِ: يَا رَبِّ! يَا رَبِّ! وَمَطْعَمُهُ حَرَامٌ، وَمَشْرَبُهُ حَرَامٌ، وَمَلْبَسُهُ حَرَامٌ، وَغُذِّيَ بِالْحَرَامِ، فَأَنَّى يُسْتَجَابُ لَهُ؟».","fr":"D’après Abû Hurayra (qu’Allah l’agrée), qui a dit : Le Messager d’Allah ﷺ a dit : « Allah le Très-Haut est bon et n’accepte que ce qui est bon. Allah a ordonné aux croyants ce qu’Il a ordonné aux messagers. Il a dit : {Ô messagers ! Mangez des bonnes choses et faites le bien}, et Il a dit : {Ô vous qui croyez ! Mangez des bonnes choses que Nous vous avons attribuées}. » Puis il mentionna l’homme qui fait un long voyage, les cheveux ébouriffés et couvert de poussière, qui tend les mains vers le ciel : « Ô Seigneur ! Ô Seigneur ! », alors que sa nourriture est illicite, sa boisson est illicite, son vêtement est illicite et qu’il a été nourri d’illicite : comment pourrait-il être exaucé ?"}]},{"id":"N11","num":11,"title":"Laisse ce qui te fait douter","titleAr":"","takeaway":"Dans le doute, choisis ce qui est sûr.","source":"Rapporté par at-Tirmidhî et an-Nasâ’î ; at-Tirmidhî a dit : hadith bon et authentique.","units":[{"id":"N11","ar":"عَنْ أَبِي مُحَمَّدٍ الْحَسَنِ بْنِ عَلِيِّ بْنِ أَبِي طَالِبٍ سِبْطِ رَسُولِ اللَّهِ ﷺ وَرَيْحَانَتِهِ رَضِيَ اللَّهُ عَنْهُمَا، قَالَ: حَفِظْت مِنْ رَسُولِ اللَّهِ ﷺ «دَعْ مَا يُرِيبُك إلَى مَا لَا يُرِيبُك». رَوَاهُ التِّرْمِذِيُّ، وَقَالَ التِّرْمِذِيُّ: حَدِيثٌ حَسَنٌ صَحِيحٌ.","fr":"D’après Abû Muhammad al-Hasan, fils de ‘Alî ibn Abî Tâlib, petit-fils et bien-aimé du Messager d’Allah ﷺ (qu’Allah les agrée), qui a dit : J’ai retenu du Messager d’Allah ﷺ : « Laisse ce qui te fait douter pour ce qui ne te fait pas douter. »"}]},{"id":"N12","num":12,"title":"Délaisser ce qui ne nous regarde pas","titleAr":"","takeaway":"Ne perds pas ton temps dans ce qui ne te concerne pas.","source":"Hadith bon, rapporté par at-Tirmidhî et d’autres.","units":[{"id":"N12","ar":"عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ «مِنْ حُسْنِ إسْلَامِ الْمَرْءِ تَرْكُهُ مَا لَا يَعْنِيهِ». حَدِيثٌ حَسَنٌ، رَوَاهُ التِّرْمِذِيُّ.","fr":"D’après Abû Hurayra (qu’Allah l’agrée), qui a dit : Le Messager d’Allah ﷺ a dit : « Fait partie de la bonne pratique de l’islam, pour une personne, le fait de délaisser ce qui ne la concerne pas. »"}]},{"id":"N13","num":13,"title":"Aimer pour son frère ce qu’on aime pour soi","titleAr":"","takeaway":"La foi complète, c’est souhaiter aux autres le bien qu’on se souhaite.","source":"Rapporté par al-Bukhârî et Muslim.","units":[{"id":"N13","ar":"عَنْ أَبِي حَمْزَةَ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ خَادِمِ رَسُولِ اللَّهِ ﷺ عَنْ النَّبِيِّ ﷺ قَالَ: «لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لِأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ». رَوَاهُ الْبُخَارِيُّ.","fr":"D’après Abû Hamza Anas ibn Mâlik (qu’Allah l’agrée), serviteur du Messager d’Allah ﷺ, d’après le Prophète ﷺ : « Aucun de vous n’a vraiment la foi tant qu’il n’aime pas pour son frère ce qu’il aime pour lui-même. »"}]},{"id":"N14","num":14,"title":"Le caractère sacré de la vie","titleAr":"","takeaway":"La vie du musulman est sacrée, sauf dans trois cas jugés par l’autorité.","source":"Rapporté par al-Bukhârî et Muslim.","units":[{"id":"N14","ar":"عَنْ ابْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ «لَا يَحِلُّ دَمُ امْرِئٍ مُسْلِمٍ إلَّا بِإِحْدَى ثَلَاثٍ: الثَّيِّبُ الزَّانِي، وَالنَّفْسُ بِالنَّفْسِ، وَالتَّارِكُ لِدِينِهِ الْمُفَارِقُ لِلْجَمَاعَةِ».","fr":"D’après Ibn Mas‘ûd (qu’Allah l’agrée), qui a dit : Le Messager d’Allah ﷺ a dit : « Le sang d’un musulman n’est licite que dans l’un de ces trois cas : l’homme marié qui commet l’adultère, la vie pour la vie, et celui qui abandonne sa religion en se séparant de la communauté. »"}]},{"id":"N15","num":15,"title":"Dire du bien ou se taire","titleAr":"","takeaway":"La foi se voit dans la parole, le voisinage et l’hospitalité.","source":"Rapporté par al-Bukhârî et Muslim.","units":[{"id":"N15","ar":"عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «مَنْ كَانَ يُؤْمِنُ بِاَللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَصْمُتْ، وَمَنْ كَانَ يُؤْمِنُ بِاَللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ جَارَهُ، وَمَنْ كَانَ يُؤْمِنُ بِاَللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ ضَيْفَهُ».","fr":"D’après Abû Hurayra (qu’Allah l’agrée) : Le Messager d’Allah ﷺ a dit : « Que celui qui croit en Allah et au Jour dernier dise du bien ou se taise ; que celui qui croit en Allah et au Jour dernier honore son voisin ; que celui qui croit en Allah et au Jour dernier honore son hôte. »"}]},{"id":"N16","num":16,"title":"Ne te mets pas en colère","titleAr":"","takeaway":"Maîtriser sa colère protège de beaucoup de maux.","source":"Rapporté par al-Bukhârî.","units":[{"id":"N16","ar":"عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ أَنَّ رَجُلًا قَالَ لِلنَّبِيِّ ﷺ أَوْصِنِي. قَالَ: لَا تَغْضَبْ، فَرَدَّدَ مِرَارًا، قَالَ: لَا تَغْضَبْ\".","fr":"D’après Abû Hurayra (qu’Allah l’agrée) : un homme dit au Prophète ﷺ : « Conseille-moi. » Il dit : « Ne te mets pas en colère. » L’homme répéta sa demande plusieurs fois, et il dit : « Ne te mets pas en colère. »"}]},{"id":"N17","num":17,"title":"L’excellence en toute chose","titleAr":"","takeaway":"Fais tout avec soin et douceur, même envers les animaux.","source":"Rapporté par Muslim.","units":[{"id":"N17","ar":"عَنْ أَبِي يَعْلَى شَدَّادِ بْنِ أَوْسٍ رَضِيَ اللهُ عَنْهُ عَنْ رَسُولِ اللَّهِ ﷺ قَالَ: «إنَّ اللَّهَ كَتَبَ الْإِحْسَانَ عَلَى كُلِّ شَيْءٍ، فَإِذَا قَتَلْتُمْ فَأَحْسِنُوا الْقِتْلَةَ، وَإِذَا ذَبَحْتُمْ فَأَحْسِنُوا الذِّبْحَةَ، وَلْيُحِدَّ أَحَدُكُمْ شَفْرَتَهُ، وَلْيُرِحْ ذَبِيحَتَهُ».","fr":"D’après Abû Ya‘lâ Chaddâd ibn Aws (qu’Allah l’agrée), d’après le Messager d’Allah ﷺ : « Allah a prescrit l’excellence en toute chose. Si vous tuez, tuez de la meilleure manière ; si vous égorgez, égorgez de la meilleure manière : que chacun aiguise sa lame et épargne la souffrance à la bête qu’il égorge. »"}]},{"id":"N18","num":18,"title":"Crains Allah où que tu sois","titleAr":"","takeaway":"La piété, le repentir par les bonnes actions et le bon caractère.","source":"Rapporté par at-Tirmidhî, qui a dit : hadith bon (et dans certaines copies : bon et authentique).","units":[{"id":"N18","ar":"عَنْ أَبِي ذَرٍّ جُنْدَبِ بْنِ جُنَادَةَ، وَأَبِي عَبْدِ الرَّحْمَنِ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللَّهُ عَنْهُمَا، عَنْ رَسُولِ اللَّهِ ﷺ قَالَ: «اتَّقِ اللَّهَ حَيْثُمَا كُنْت، وَأَتْبِعْ السَّيِّئَةَ الْحَسَنَةَ تَمْحُهَا، وَخَالِقْ النَّاسَ بِخُلُقٍ حَسَنٍ». رَوَاهُ التِّرْمِذِيُّ وَقَالَ: حَدِيثٌ حَسَنٌ، وَفِي بَعْضِ النُّسَخِ: حَسَنٌ صَحِيحٌ.","fr":"D’après Abû Dharr Jundub ibn Junâda et Abû ‘Abd ar-Rahmân Mu‘âdh ibn Jabal (qu’Allah les agrée), d’après le Messager d’Allah ﷺ : « Crains Allah où que tu sois ; fais suivre la mauvaise action d’une bonne, elle l’effacera ; et comporte-toi avec les gens avec un bon caractère. »"}]},{"id":"N19","num":19,"title":"Préserve Allah, Il te préservera","titleAr":"","takeaway":"Demande à Allah seul : rien ne t’atteint sans qu’Il l’ait écrit.","source":"Rapporté par at-Tirmidhî, qui a dit : hadith bon et authentique.","units":[{"id":"N19","ar":"عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: «كُنْت خَلْفَ رَسُولِ اللَّهِ ﷺ يَوْمًا، فَقَالَ: يَا غُلَامِ! إنِّي أُعَلِّمُك كَلِمَاتٍ: احْفَظْ اللَّهَ يَحْفَظْك، احْفَظْ اللَّهَ تَجِدْهُ تُجَاهَك، إذَا سَأَلْت فَاسْأَلْ اللَّهَ، وَإِذَا اسْتَعَنْت فَاسْتَعِنْ بِاَللَّهِ، وَاعْلَمْ أَنَّ الْأُمَّةَ لَوْ اجْتَمَعَتْ عَلَى أَنْ يَنْفَعُوك بِشَيْءٍ لَمْ يَنْفَعُوك إلَّا بِشَيْءٍ قَدْ كَتَبَهُ اللَّهُ لَك، وَإِنْ اجْتَمَعُوا عَلَى أَنْ يَضُرُّوك بِشَيْءٍ لَمْ يَضُرُّوك إلَّا بِشَيْءٍ قَدْ كَتَبَهُ اللَّهُ عَلَيْك؛ رُفِعَتْ الْأَقْلَامُ، وَجَفَّتْ الصُّحُفُ». رَوَاهُ التِّرْمِذِيُّ وَقَالَ: حَدِيثٌ حَسَنٌ صَحِيحٌ. وَفِي رِوَايَةِ غَيْرِ التِّرْمِذِيِّ: «احْفَظْ اللَّهَ تَجِدْهُ أمامك، تَعَرَّفْ إلَى اللَّهِ فِي الرَّخَاءِ يَعْرِفُك فِي الشِّدَّةِ، وَاعْلَمْ أَنَّ مَا أَخْطَأَك لَمْ يَكُنْ لِيُصِيبَك، وَمَا أَصَابَك لَمْ يَكُنْ لِيُخْطِئَك، وَاعْلَمْ أَنَّ النَّصْرَ مَعَ الصَّبْرِ، وَأَنْ الْفَرَجَ مَعَ الْكَرْبِ، وَأَنَّ مَعَ الْعُسْرِ يُسْرًا».","fr":"D’après Abû al-‘Abbâs ‘Abd Allâh ibn ‘Abbâs (qu’Allah les agrée), qui a dit : J’étais un jour derrière le Prophète ﷺ, et il me dit : « Ô jeune garçon, je vais t’apprendre quelques paroles : préserve (les droits d’)Allah, Il te préservera ; préserve Allah, tu Le trouveras devant toi. Si tu demandes, demande à Allah ; si tu cherches de l’aide, cherche-la auprès d’Allah. Sache que si la communauté entière se réunissait pour te faire profiter de quelque chose, elle ne te ferait profiter que de ce qu’Allah a déjà écrit pour toi ; et si elle se réunissait pour te nuire, elle ne te nuirait que par ce qu’Allah a déjà écrit contre toi. Les calames ont été levés et les feuilles ont séché. » Dans une autre version : « Préserve Allah, tu Le trouveras devant toi. Fais-toi connaître d’Allah dans l’aisance, Il te connaîtra dans l’adversité. Sache que ce qui t’a manqué ne pouvait pas t’atteindre, et que ce qui t’a atteint ne pouvait pas te manquer. Sache que la victoire vient avec la patience, la délivrance avec l’épreuve, et qu’avec la difficulté vient la facilité. »"}]},{"id":"N20","num":20,"title":"La pudeur","titleAr":"","takeaway":"La pudeur retient de mal agir : c’est un enseignement de tous les prophètes.","source":"Rapporté par al-Bukhârî.","units":[{"id":"N20","ar":"عَنْ أَبِي مَسْعُودٍ عُقْبَةَ بْنِ عَمْرٍو الْأَنْصَارِيِّ الْبَدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ «إنَّ مِمَّا أَدْرَكَ النَّاسُ مِنْ كَلَامِ النُّبُوَّةِ الْأُولَى: إذَا لَمْ تَسْتَحِ فَاصْنَعْ مَا شِئْت».","fr":"D’après Abû Mas‘ûd ‘Uqba ibn ‘Amr al-Ansârî al-Badrî (qu’Allah l’agrée), qui a dit : Le Messager d’Allah ﷺ a dit : « Parmi ce que les gens ont retenu des paroles de la première prophétie : si tu n’as pas de pudeur, fais ce que tu veux. »"}]},{"id":"N21","num":21,"title":"Crois en Allah, puis sois droit","titleAr":"","takeaway":"La foi et la droiture résument toute la religion.","source":"Rapporté par Muslim.","units":[{"id":"N21","ar":"عَنْ أَبِي عَمْرٍو وَقِيلَ: أَبِي عَمْرَةَ سُفْيَانَ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُ قَالَ: «قُلْت: يَا رَسُولَ اللَّهِ! قُلْ لِي فِي الْإِسْلَامِ قَوْلًا لَا أَسْأَلُ عَنْهُ أَحَدًا غَيْرَك؛ قَالَ: قُلْ: آمَنْت بِاَللَّهِ ثُمَّ اسْتَقِمْ».","fr":"D’après Abû ‘Amr — on dit aussi Abû ‘Amra — Sufyân ibn ‘Abd Allâh (qu’Allah l’agrée), qui a dit : J’ai dit : « Ô Messager d’Allah, dis-moi au sujet de l’islam une parole sur laquelle je n’aurai à interroger personne d’autre que toi. » Il dit : « Dis : “Je crois en Allah”, puis sois droit. »"}]},{"id":"N22","num":22,"title":"Le chemin du Paradis","titleAr":"","takeaway":"Accomplir les obligations et respecter le licite et l’illicite mène au Paradis.","source":"Rapporté par Muslim.","units":[{"id":"N22","ar":"عَنْ أَبِي عَبْدِ اللَّهِ جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُمَا: «أَنَّ رَجُلًا سَأَلَ رَسُولَ اللَّهِ ﷺ فَقَالَ: أَرَأَيْت إذَا صَلَّيْت الْمَكْتُوبَاتِ، وَصُمْت رَمَضَانَ، وَأَحْلَلْت الْحَلَالَ، وَحَرَّمْت الْحَرَامَ، وَلَمْ أَزِدْ عَلَى ذَلِكَ شَيْئًا؛ أَأَدْخُلُ الْجَنَّةَ؟ قَالَ: نَعَمْ».","fr":"D’après Abû ‘Abd Allâh Jâbir ibn ‘Abd Allâh al-Ansârî (qu’Allah les agrée) : un homme interrogea le Messager d’Allah ﷺ : « Dis-moi : si je prie les prières obligatoires, jeûne le Ramadan, considère licite ce qui est licite et illicite ce qui est illicite, sans rien ajouter à cela, entrerai-je au Paradis ? » Il dit : « Oui. »"}]},{"id":"N23","num":23,"title":"La purification est la moitié de la foi","titleAr":"","takeaway":"Chaque dhikr, prière et aumône est une lumière pour le croyant.","source":"Rapporté par Muslim.","units":[{"id":"N23","ar":"عَنْ أَبِي مَالِكٍ الْحَارِثِ بْنِ عَاصِمٍ الْأَشْعَرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ «الطَّهُورُ شَطْرُ الْإِيمَانِ، وَالْحَمْدُ لِلَّهِ تَمْلَأُ الْمِيزَانَ، وَسُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ تَمْلَآنِ -أَوْ: تَمْلَأُ- مَا بَيْنَ السَّمَاءِ وَالْأَرْضِ، وَالصَّلَاةُ نُورٌ، وَالصَّدَقَةُ بُرْهَانٌ، وَالصَّبْرُ ضِيَاءٌ، وَالْقُرْآنُ حُجَّةٌ لَك أَوْ عَلَيْك، كُلُّ النَّاسِ يَغْدُو، فَبَائِعٌ نَفْسَهُ فَمُعْتِقُهَا أَوْ مُوبِقُهَا».","fr":"D’après Abû Mâlik al-Hârith ibn ‘Âsim al-Ach‘arî (qu’Allah l’agrée), qui a dit : Le Messager d’Allah ﷺ a dit : « La purification est la moitié de la foi ; “al-hamdu lillâh” remplit la balance ; “subhâna-llâh” et “al-hamdu lillâh” remplissent ce qui est entre les cieux et la terre ; la prière est une lumière ; l’aumône est une preuve ; la patience est une clarté ; et le Coran est un argument pour toi ou contre toi. Chacun part au matin et vend son âme : il l’affranchit ou la mène à sa perte. »"}]},{"id":"N24","num":24,"title":"L’interdiction de l’injustice (hadith qudsî)","titleAr":"","takeaway":"Allah s’est interdit l’injustice : ne soyez pas injustes entre vous.","source":"Rapporté par Muslim.","units":[{"id":"N24","ar":"عَنْ أَبِي ذَرٍّ الْغِفَارِيِّ رَضِيَ اللهُ عَنْهُ عَنْ النَّبِيِّ ﷺ فِيمَا يَرْوِيهِ عَنْ رَبِّهِ تَبَارَكَ وَتَعَالَى، أَنَّهُ قَالَ: «يَا عِبَادِي: إنِّي حَرَّمْت الظُّلْمَ عَلَى نَفْسِي، وَجَعَلْته بَيْنَكُمْ مُحَرَّمًا؛ فَلَا تَظَالَمُوا. يَا عِبَادِي! كُلُّكُمْ ضَالٌّ إلَّا مَنْ هَدَيْته، فَاسْتَهْدُونِي أَهْدِكُمْ. يَا عِبَادِي! كُلُّكُمْ جَائِعٌ إلَّا مَنْ أَطْعَمْته، فَاسْتَطْعِمُونِي أُطْعِمْكُمْ. يَا عِبَادِي! كُلُّكُمْ عَارٍ إلَّا مَنْ كَسَوْته، فَاسْتَكْسُونِي أَكْسُكُمْ. يَا عِبَادِي! إنَّكُمْ تُخْطِئُونَ بِاللَّيْلِ وَالنَّهَارِ، وَأَنَا أَغْفِرُ الذُّنُوبَ جَمِيعًا؛ فَاسْتَغْفِرُونِي أَغْفِرْ لَكُمْ. يَا عِبَادِي! إنَّكُمْ لَنْ تَبْلُغُوا ضُرِّي فَتَضُرُّونِي، وَلَنْ تَبْلُغُوا نَفْعِي فَتَنْفَعُونِي. يَا عِبَادِي! لَوْ أَنَّ أَوَّلَكُمْ وَآخِرَكُمْ وَإِنْسَكُمْ وَجِنَّكُمْ كَانُوا عَلَى أَتْقَى قَلْبِ رَجُلٍ وَاحِدٍ مِنْكُمْ، مَا زَادَ ذَلِكَ فِي مُلْكِي شَيْئًا. يَا عِبَادِي! لَوْ أَنَّ أَوَّلَكُمْ وَآخِرَكُمْ وَإِنْسَكُمْ وَجِنَّكُمْ كَانُوا عَلَى أَفْجَرِ قَلْبِ رَجُلٍ وَاحِدٍ مِنْكُمْ، مَا نَقَصَ ذَلِكَ مِنْ مُلْكِي شَيْئًا. يَا عِبَادِي! لَوْ أَنَّ أَوَّلَكُمْ وَآخِرَكُمْ وَإِنْسَكُمْ وَجِنَّكُمْ قَامُوا فِي صَعِيدٍ وَاحِدٍ، فَسَأَلُونِي، فَأَعْطَيْت كُلَّ وَاحِدٍ مَسْأَلَته، مَا نَقَصَ ذَلِكَ مِمَّا عِنْدِي إلَّا كَمَا يَنْقُصُ الْمِخْيَطُ إذَا أُدْخِلَ الْبَحْرَ. يَا عِبَادِي! إنَّمَا هِيَ أَعْمَالُكُمْ أُحْصِيهَا لَكُمْ، ثُمَّ أُوَفِّيكُمْ إيَّاهَا؛ فَمَنْ وَجَدَ خَيْرًا فَلْيَحْمَدْ اللَّهَ، وَمَنْ وَجَدَ غَيْرَ ذَلِكَ فَلَا يَلُومَن إلَّا نَفْسَهُ».","fr":"D’après Abû Dharr al-Ghifârî (qu’Allah l’agrée), d’après le Prophète ﷺ, dans ce qu’il rapporte de son Seigneur, Puissant et Majestueux : « Ô Mes serviteurs ! Je Me suis interdit l’injustice et Je l’ai rendue illicite entre vous : ne vous faites donc pas d’injustice. Ô Mes serviteurs ! Vous êtes tous égarés, sauf celui que J’ai guidé : demandez-Moi la guidée, Je vous guiderai. Ô Mes serviteurs ! Vous avez tous faim, sauf celui que J’ai nourri : demandez-Moi de quoi manger, Je vous nourrirai. Ô Mes serviteurs ! Vous êtes tous nus, sauf celui que J’ai vêtu : demandez-Moi de quoi vous vêtir, Je vous vêtirai. Ô Mes serviteurs ! Vous péchez nuit et jour, et Je pardonne tous les péchés : demandez-Moi pardon, Je vous pardonnerai. Ô Mes serviteurs ! Vous ne pourrez jamais Me nuire, ni Me profiter. Ô Mes serviteurs ! Si le premier et le dernier d’entre vous, vos hommes et vos djinns, avaient le cœur du plus pieux d’entre vous, cela n’ajouterait rien à Mon royaume. Ô Mes serviteurs ! Si le premier et le dernier d’entre vous, vos hommes et vos djinns, avaient le cœur du plus pervers d’entre vous, cela ne diminuerait en rien Mon royaume. Ô Mes serviteurs ! Si le premier et le dernier d’entre vous, vos hommes et vos djinns, se tenaient en un même lieu et Me demandaient, et que Je donnais à chacun ce qu’il demande, cela ne diminuerait ce que Je possède que comme l’aiguille diminue l’océan quand on l’y plonge. Ô Mes serviteurs ! Ce ne sont que vos œuvres que Je compte pour vous, puis Je vous en rétribue pleinement. Que celui qui trouve un bien loue Allah, et que celui qui trouve autre chose ne blâme que lui-même. »"}]},{"id":"N25","num":25,"title":"Toute bonne action est une aumône","titleAr":"","takeaway":"Le dhikr, le bien et même la vie de couple licite sont des aumônes.","source":"Rapporté par Muslim.","units":[{"id":"N25","ar":"عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ أَيْضًا، «أَنَّ نَاسًا مِنْ أَصْحَابِ رَسُولِ اللَّهِ ﷺ قَالُوا لِلنَّبِيِّ ﷺ يَا رَسُولَ اللَّهِ ذَهَبَ أَهْلُ الدُّثُورِ بِالْأُجُورِ؛ يُصَلُّونَ كَمَا نُصَلِّي، وَيَصُومُونَ كَمَا نَصُومُ، وَيَتَصَدَّقُونَ بِفُضُولِ أَمْوَالِهِمْ. قَالَ: أَوَلَيْسَ قَدْ جَعَلَ اللَّهُ لَكُمْ مَا تَصَّدَّقُونَ؟ إنَّ بِكُلِّ تَسْبِيحَةٍ صَدَقَةً، وَكُلِّ تَكْبِيرَةٍ صَدَقَةً، وَكُلِّ تَحْمِيدَةٍ صَدَقَةً، وَكُلِّ تَهْلِيلَةٍ صَدَقَةً، وَأَمْرٌ بِمَعْرُوفٍ صَدَقَةٌ، وَنَهْيٌ عَنْ مُنْكَرٍ صَدَقَةٌ، وَفِي بُضْعِ أَحَدِكُمْ صَدَقَةٌ. قَالُوا: يَا رَسُولَ اللَّهِ أَيَأْتِي أَحَدُنَا شَهْوَتَهُ وَيَكُونُ لَهُ فِيهَا أَجْرٌ؟ قَالَ: أَرَأَيْتُمْ لَوْ وَضَعَهَا فِي حَرَامٍ أَكَانَ عَلَيْهِ وِزْرٌ؟ فَكَذَلِكَ إذَا وَضَعَهَا فِي الْحَلَالِ، كَانَ لَهُ أَجْرٌ».","fr":"D’après Abû Dharr (qu’Allah l’agrée) également : des compagnons du Messager d’Allah ﷺ lui dirent : « Ô Messager d’Allah, les gens aisés emportent les récompenses : ils prient comme nous prions, jeûnent comme nous jeûnons, et font l’aumône avec le surplus de leurs biens. » Il dit : « Allah ne vous a-t-Il pas donné de quoi faire l’aumône ? Chaque “subhâna-llâh” est une aumône, chaque “Allâhu akbar” est une aumône, chaque “al-hamdu lillâh” est une aumône, chaque “lâ ilâha illa-llâh” est une aumône ; ordonner le convenable est une aumône ; interdire le blâmable est une aumône ; et l’union de l’un de vous avec son épouse est une aumône. » Ils dirent : « Ô Messager d’Allah, l’un de nous satisfait son désir et il en aurait une récompense ? » Il dit : « Dites-moi : s’il l’avait satisfait dans l’illicite, n’aurait-il pas un péché ? De même, s’il le satisfait dans le licite, il a une récompense. »"}]},{"id":"N26","num":26,"title":"Une aumône pour chaque articulation","titleAr":"","takeaway":"Chaque jour, remercie Allah par de petites bonnes actions.","source":"Rapporté par al-Bukhârî et Muslim.","units":[{"id":"N26","ar":"عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ «كُلُّ سُلَامَى مِنْ النَّاسِ عَلَيْهِ صَدَقَةٌ، كُلَّ يَوْمٍ تَطْلُعُ فِيهِ الشَّمْسُ تَعْدِلُ بَيْنَ اثْنَيْنِ صَدَقَةٌ، وَتُعِينُ الرَّجُلَ فِي دَابَّتِهِ فَتَحْمِلُهُ عَلَيْهَا أَوْ تَرْفَعُ لَهُ عَلَيْهَا مَتَاعَهُ صَدَقَةٌ، وَالْكَلِمَةُ الطَّيِّبَةُ صَدَقَةٌ، وَبِكُلِّ خُطْوَةٍ تَمْشِيهَا إلَى الصَّلَاةِ صَدَقَةٌ، وَتُمِيطُ الْأَذَى عَنْ الطَّرِيقِ صَدَقَةٌ».","fr":"D’après Abû Hurayra (qu’Allah l’agrée), qui a dit : Le Messager d’Allah ﷺ a dit : « Pour chaque articulation des gens, une aumône est due chaque jour où le soleil se lève : établir la justice entre deux personnes est une aumône ; aider un homme à monter sur sa monture ou à y charger ses affaires est une aumône ; la bonne parole est une aumône ; chaque pas que tu fais vers la prière est une aumône ; et écarter ce qui gêne du chemin est une aumône. »"}]},{"id":"N27","num":27,"title":"La piété, c’est le bon caractère","titleAr":"","takeaway":"Le péché trouble le cœur : consulte ton cœur.","source":"Hadith bon, rapporté dans les Musnad des imams Ahmad ibn Hanbal et ad-Dârimî avec une chaîne bonne.","units":[{"id":"N27","ar":"عَنْ النَّوَّاسِ بْنِ سَمْعَانَ رَضِيَ اللهُ عَنْهُ عَنْ النَّبِيِّ ﷺ قَالَ: «الْبِرُّ حُسْنُ الْخُلُقِ، وَالْإِثْمُ مَا حَاكَ فِي صَدْرِك، وَكَرِهْت أَنْ يَطَّلِعَ عَلَيْهِ النَّاسُ» رَوَاهُ مُسْلِمٌ. وَعَنْ وَابِصَةَ بْنِ مَعْبَدٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْت رَسُولَ اللَّهِ ﷺ فَقَالَ: «جِئْتَ تَسْأَلُ عَنْ الْبِرِّ؟ قُلْت: نَعَمْ. فقَالَ: استفت قلبك، الْبِرُّ مَا اطْمَأَنَّتْ إلَيْهِ النَّفْسُ، وَاطْمَأَنَّ إلَيْهِ الْقَلْبُ، وَالْإِثْمُ مَا حَاكَ فِي النَّفْسِ وَتَرَدَّدَ فِي الصَّدْرِ، وَإِنْ أَفْتَاك النَّاسُ وَأَفْتَوْك». حَدِيثٌ حَسَنٌ، رَوَيْنَاهُ في مُسْنَدَي الْإِمَامَيْنِ أَحْمَدَ بْنِ حَنْبَلٍ بِإِسْنَادٍ حَسَنٍ.","fr":"D’après an-Nawwâs ibn Sam‘ân (qu’Allah l’agrée), d’après le Prophète ﷺ : « La piété, c’est le bon caractère ; et le péché, c’est ce qui trouble ton âme et que tu détesterais que les gens découvrent. » (Rapporté par Muslim.) Et d’après Wâbisa ibn Ma‘bad (qu’Allah l’agrée), qui a dit : Je vins voir le Messager d’Allah ﷺ, et il me dit : « Es-tu venu m’interroger sur la piété ? » Je dis : « Oui. » Il dit : « Consulte ton cœur. La piété est ce en quoi l’âme est apaisée et le cœur tranquille ; le péché est ce qui trouble l’âme et hésite dans la poitrine, même si les gens te donnent leur avis, et encore leur avis. »"}]},{"id":"N28","num":28,"title":"S’attacher à la sunna","titleAr":"","takeaway":"Suis la sunna du Prophète et des califes bien guidés, et évite les innovations.","source":"Rapporté par Abû Dâwûd et at-Tirmidhî, qui a dit : hadith bon et authentique.","units":[{"id":"N28","ar":"عَنْ أَبِي نَجِيحٍ الْعِرْبَاضِ بْنِ سَارِيَةَ رَضِيَ اللهُ عَنْهُ قَالَ: «وَعَظَنَا رَسُولُ اللَّهِ ﷺ مَوْعِظَةً وَجِلَتْ مِنْهَا الْقُلُوبُ، وَذَرَفَتْ مِنْهَا الْعُيُونُ، فَقُلْنَا: يَا رَسُولَ اللَّهِ! كَأَنَّهَا مَوْعِظَةُ مُوَدِّعٍ فَأَوْصِنَا، قَالَ: أُوصِيكُمْ بِتَقْوَى اللَّهِ، وَالسَّمْعِ وَالطَّاعَةِ وَإِنْ تَأَمَّرَ عَلَيْكُمْ عَبْدٌ، فَإِنَّهُ مَنْ يَعِشْ مِنْكُمْ فَسَيَرَى اخْتِلَافًا كَثِيرًا، فَعَلَيْكُمْ بِسُنَّتِي وَسُنَّةِ الْخُلَفَاءِ الرَّاشِدِينَ الْمَهْدِيينَ، عَضُّوا عَلَيْهَا بِالنَّوَاجِذِ، وَإِيَّاكُمْ وَمُحْدَثَاتِ الْأُمُورِ؛ فَإِنَّ كُلَّ بِدْعَةٍ ضَلَالَةٌ». وَقَالَ: حَدِيثٌ حَسَنٌ صَحِيحٌ.","fr":"D’après Abû Najîh al-‘Irbâd ibn Sâriya (qu’Allah l’agrée), qui a dit : Le Messager d’Allah ﷺ nous fit une exhortation qui fit trembler les cœurs et couler les larmes. Nous dîmes : « Ô Messager d’Allah, on dirait l’exhortation de quelqu’un qui fait ses adieux : fais-nous donc des recommandations. » Il dit : « Je vous recommande la crainte d’Allah, et d’écouter et d’obéir, même si c’est un esclave qui vous dirige. Celui d’entre vous qui vivra verra beaucoup de divergences : attachez-vous donc à ma sunna et à la sunna des califes bien guidés et guidants, mordez-y avec les molaires. Et prenez garde aux choses nouvelles (dans la religion), car toute innovation est un égarement. »"}]},{"id":"N29","num":29,"title":"Les actes qui font entrer au Paradis","titleAr":"","takeaway":"Garde ta langue : c’est elle qui maîtrise tout le reste.","source":"Rapporté par at-Tirmidhî, qui a dit : hadith bon et authentique.","units":[{"id":"N29","ar":"عَنْ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْت يَا رَسُولَ اللَّهِ! أَخْبِرْنِي بِعَمَلٍ يُدْخِلُنِي الْجَنَّةَ وَيُبَاعِدْنِي مِنْ النَّارِ، قَالَ: «لَقَدْ سَأَلْت عَنْ عَظِيمٍ، وَإِنَّهُ لَيَسِيرٌ عَلَى مَنْ يَسَّرَهُ اللَّهُ عَلَيْهِ: تَعْبُدُ اللَّهَ لَا تُشْرِكْ بِهِ شَيْئًا، وَتُقِيمُ الصَّلَاةَ، وَتُؤْتِي الزَّكَاةَ، وَتَصُومُ رَمَضَانَ، وَتَحُجُّ الْبَيْتَ، ثُمَّ قَالَ: أَلَا أَدُلُّك عَلَى أَبْوَابِ الْخَيْرِ؟ الصَّوْمُ جُنَّةٌ، وَالصَّدَقَةُ تُطْفِئُ الْخَطِيئَةَ كَمَا يُطْفِئُ الْمَاءُ النَّارَ، وَصَلَاةُ الرَّجُلِ فِي جَوْفِ اللَّيْلِ، ثُمَّ تَلَا:» تَتَجَافَى جُنُوبُهُمْ عَنِ الْمَضَاجِعِ «حَتَّى بَلَغَ»يَعْمَلُونَ«، ثُمَّ قَالَ: أَلَا أُخْبِرُك بِرَأْسِ الْأَمْرِ وَعَمُودِهِ وَذُرْوَةِ سَنَامِهِ؟ قُلْت: بَلَى يَا رَسُولَ اللَّهِ. قَالَ: رَأْسُ الْأَمْرِ الْإِسْلَامُ، وَعَمُودُهُ الصَّلَاةُ، وَذُرْوَةُ سَنَامِهِ الْجِهَادُ، ثُمَّ قَالَ: أَلَا أُخْبِرُك بِمَلَاكِ ذَلِكَ كُلِّهِ؟ فقُلْت: بَلَى يَا رَسُولَ اللَّهِ ! فَأَخَذَ بِلِسَانِهِ وَقَالَ: كُفَّ عَلَيْك هَذَا. قُلْت: يَا نَبِيَّ اللَّهِ وَإِنَّا لَمُؤَاخَذُونَ بِمَا نَتَكَلَّمُ بِهِ؟ فَقَالَ: ثَكِلَتْك أُمُّك وَهَلْ يَكُبُّ النَّاسَ عَلَى وُجُوهِهِمْ -أَوْ قَالَ عَلَى مَنَاخِرِهِمْ- إلَّا حَصَائِدُ أَلْسِنَتِهِمْ؟!». رَوَاهُ التِّرْمِذِيُّ وَقَالَ: حَدِيثٌ حَسَنٌ صَحِيحٌ.","fr":"D’après Mu‘âdh ibn Jabal (qu’Allah l’agrée), qui a dit : J’ai dit : « Ô Messager d’Allah, informe-moi d’un acte qui me fera entrer au Paradis et m’éloignera de l’Enfer. » Il dit : « Tu as demandé une chose immense, mais elle est facile pour celui à qui Allah la rend facile : adore Allah sans rien Lui associer, accomplis la prière, acquitte la zakât, jeûne le Ramadan et fais le pèlerinage à la Maison. » Puis il dit : « Ne t’indiquerai-je pas les portes du bien ? Le jeûne est un bouclier ; l’aumône efface le péché comme l’eau éteint le feu ; et la prière de l’homme au milieu de la nuit. » Puis il récita : {Ils s’arrachent de leurs lits…} jusqu’à {…pour ce qu’ils faisaient}. Puis il dit : « Ne t’informerai-je pas de la tête de l’affaire, de son pilier et du sommet de sa bosse ? » Je dis : « Si, ô Messager d’Allah. » Il dit : « La tête de l’affaire est l’islam, son pilier est la prière, et le sommet de sa bosse est le jihâd. » Puis il dit : « Ne t’informerai-je pas de ce qui maîtrise tout cela ? » Je dis : « Si, ô Messager d’Allah. » Il prit sa langue et dit : « Retiens ceci. » Je dis : « Ô Prophète d’Allah, serons-nous tenus pour responsables de ce que nous disons ? » Il dit : « Que ta mère te perde, ô Mu‘âdh ! Qu’est-ce qui jette les gens en Enfer sur leur visage — ou sur leur nez — sinon les récoltes de leurs langues ? »"}]},{"id":"N30","num":30,"title":"Les limites d’Allah","titleAr":"","takeaway":"Respecte les obligations et les limites, et ne cherche pas à compliquer ce qu’Allah a laissé libre.","source":"Hadith bon, rapporté par ad-Dâraqutnî dans ses Sunan, et d’autres.","units":[{"id":"N30","ar":"عَنْ أَبِي ثَعْلَبَةَ الْخُشَنِيِّ جُرْثُومِ بن نَاشِر رَضِيَ اللهُ عَنْهُ عَنْ رَسُولِ اللَّهِ ﷺ قَال: «إنَّ اللَّهَ تَعَالَى فَرَضَ فَرَائِضَ فَلَا تُضَيِّعُوهَا، وَحَدَّ حُدُودًا فَلَا تَعْتَدُوهَا، وَحَرَّمَ أَشْيَاءَ فَلَا تَنْتَهِكُوهَا، وَسَكَتَ عَنْ أَشْيَاءَ رَحْمَةً لَكُمْ غَيْرَ نِسْيَانٍ فَلَا تَبْحَثُوا عَنْهَا». حَدِيثٌ حَسَنٌ، رَوَاهُ الدَّارَقُطْنِيّ ْ«في سننه»، وَغَيْرُهُ.","fr":"D’après Abû Tha‘laba al-Khuchanî Jurthûm ibn Nâchir (qu’Allah l’agrée), d’après le Messager d’Allah ﷺ : « Allah le Très-Haut a imposé des obligations : ne les négligez pas ; Il a fixé des limites : ne les transgressez pas ; Il a interdit des choses : ne les violez pas ; et Il S’est tu sur des choses, par miséricorde pour vous et non par oubli : ne faites pas de recherches à leur sujet. »"}]},{"id":"N31","num":31,"title":"Le vrai renoncement","titleAr":"","takeaway":"Ne t’attache pas à ce monde ni aux biens des autres.","source":"Hadith bon, rapporté par Ibn Mâja et d’autres avec de bonnes chaînes.","units":[{"id":"N31","ar":"عَنْ أَبِي الْعَبَّاسِ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيّ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إلَى النَّبِيِّ ﷺ فَقَالَ: يَا رَسُولَ اللهِ! دُلَّنِي عَلَى عَمَلٍ إذَا عَمِلْتُهُ أَحَبَّنِي اللهُ وَأَحَبَّنِي النَّاسُ؛ فَقَالَ: «ازْهَدْ فِي الدُّنْيَا يُحِبَّك اللهُ، وَازْهَدْ فِيمَا عِنْدَ النَّاسِ يُحِبَّك النَّاسُ». حديث حسن، رَوَاهُ ابْنُ مَاجَهْ، وَغَيْرُهُ بِأَسَانِيدَ حَسَنَةٍ.","fr":"D’après Abû al-‘Abbâs Sahl ibn Sa‘d as-Sâ‘idî (qu’Allah l’agrée), qui a dit : Un homme vint trouver le Prophète ﷺ et dit : « Ô Messager d’Allah, indique-moi un acte qui, si je l’accomplis, me fera aimer d’Allah et aimer des gens. » Il dit : « Renonce à ce monde, Allah t’aimera ; renonce à ce que possèdent les gens, les gens t’aimeront. »"}]},{"id":"N32","num":32,"title":"Ni nuire, ni rendre le mal","titleAr":"","takeaway":"Il est interdit de nuire aux autres, même en représailles excessives.","source":"Hadith bon, rapporté par Ibn Mâja, ad-Dâraqutnî et d’autres avec une chaîne remontant au Prophète ; Mâlik l’a rapporté dans le Muwatta’ d’après ‘Amr ibn Yahyâ, d’après son père, d’après le Prophète ﷺ, sans mentionner Abû Sa‘îd ; il a des voies qui se renforcent mutuellement.","units":[{"id":"N32","ar":"عَنْ أَبِي سَعِيدٍ سَعْدِ بْنِ مَالِكِ بْنِ سِنَانٍ الْخُدْرِيّ رَضِيَ اللهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «لَا ضَرَرَ وَلَا ضِرَارَ». حَدِيثٌ حَسَنٌ، رَوَاهُ ابْنُ مَاجَهْ فِي «الْمُوَطَّإِ» عَنْ عَمْرِو بْنِ يَحْيَى عَنْ أَبِيهِ عَنْ النَّبِيِّ ﷺ مُرْسَلًا، فَأَسْقَطَ أَبَا سَعِيدٍ، وَلَهُ طُرُقٌ يُقَوِّي بَعْضُهَا بَعْضًا.","fr":"D’après Abû Sa‘îd Sa‘d ibn Mâlik ibn Sinân al-Khudrî (qu’Allah l’agrée) : Le Messager d’Allah ﷺ a dit : « Ni nuire, ni rendre le mal par le mal. »"}]},{"id":"N33","num":33,"title":"La preuve incombe au demandeur","titleAr":"","takeaway":"Celui qui réclame doit prouver ; celui qui nie prête serment.","source":"Hadith bon, rapporté ainsi par al-Bayhaqî et d’autres ; une partie se trouve dans les deux Sahîh.","units":[{"id":"N33","ar":"عَنْ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «لَوْ يُعْطَى النَّاسُ بِدَعْوَاهُمْ لَادَّعَى رِجَالٌ أَمْوَالَ قَوْمٍ وَدِمَاءَهُمْ، لَكِنَّ الْبَيِّنَةَ عَلَى الْمُدَّعِي، وَالْيَمِينَ عَلَى مَنْ أَنْكَرَ». حَدِيثٌ حَسَنٌ، رَوَاهُ الْبَيْهَقِيّ، وَغَيْرُهُ هَكَذَا، وَبَعْضُهُ فِي «الصَّحِيحَيْنِ».","fr":"D’après Ibn ‘Abbâs (qu’Allah les agrée) : Le Messager d’Allah ﷺ a dit : « Si l’on donnait aux gens selon leurs seules prétentions, des hommes réclameraient les biens et le sang d’autres hommes ; mais la preuve incombe au demandeur, et le serment à celui qui nie. »"}]},{"id":"N34","num":34,"title":"Changer le blâmable","titleAr":"","takeaway":"Agis contre le mal selon ta capacité : par la main, la langue, ou au moins le cœur.","source":"Rapporté par Muslim.","units":[{"id":"N34","ar":"عَنْ أَبِي سَعِيدٍ الْخُدْرِيّ رَضِيَ اللهُ عَنْهُ قَالَ سَمِعْت رَسُولَ اللَّهِ ﷺ يَقُولُ: «مَنْ رَأَى مِنْكُمْ مُنْكَرًا فَلْيُغَيِّرْهُ بِيَدِهِ، فَإِنْ لَمْ يَسْتَطِعْ فَبِلِسَانِهِ، فَإِنْ لَمْ يَسْتَطِعْ فَبِقَلْبِهِ، وَذَلِكَ أَضْعَفُ الْإِيمَانِ».","fr":"D’après Abû Sa‘îd al-Khudrî (qu’Allah l’agrée), qui a dit : J’ai entendu le Messager d’Allah ﷺ dire : « Que celui d’entre vous qui voit un blâmable le change par sa main ; s’il ne le peut pas, par sa langue ; et s’il ne le peut pas, par son cœur : c’est là le plus faible degré de la foi. »"}]},{"id":"N35","num":35,"title":"La fraternité en islam","titleAr":"","takeaway":"Le musulman est le frère du musulman : son sang, ses biens et son honneur sont sacrés.","source":"Rapporté par Muslim.","units":[{"id":"N35","ar":"عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ «لَا تَحَاسَدُوا، وَلَا تَنَاجَشُوا، وَلَا تَبَاغَضُوا، وَلَا تَدَابَرُوا، وَلَا يَبِعْ بَعْضُكُمْ عَلَى بَيْعِ بَعْضٍ، وَكُونُوا عِبَادَ اللَّهِ إخْوَانًا، الْمُسْلِمُ أَخُو الْمُسْلِمِ، لَا يَظْلِمُهُ، وَلَا يَخْذُلُهُ، وَلَا يَكْذِبُهُ، وَلَا يَحْقِرُهُ، التَّقْوَى هَاهُنَا، وَيُشِيرُ إلَى صَدْرِهِ ثَلَاثَ مَرَّاتٍ، بِحَسْبِ امْرِئٍ مِنْ الشَّرِّ أَنْ يَحْقِرَ أَخَاهُ الْمُسْلِمَ، كُلُّ الْمُسْلِمِ عَلَى الْمُسْلِمِ حَرَامٌ: دَمُهُ وَمَالُهُ وَعِرْضُهُ».","fr":"D’après Abû Hurayra (qu’Allah l’agrée), qui a dit : Le Messager d’Allah ﷺ a dit : « Ne vous enviez pas ; ne faites pas monter les prix les uns contre les autres ; ne vous haïssez pas ; ne vous tournez pas le dos ; et que l’un de vous ne vende pas par-dessus la vente d’un autre. Soyez, ô serviteurs d’Allah, des frères. Le musulman est le frère du musulman : il ne lui fait pas d’injustice, ne l’abandonne pas, ne lui ment pas et ne le méprise pas. La piété est ici — et il montra sa poitrine trois fois. Il suffit à un homme, comme mal, de mépriser son frère musulman. Tout le musulman est sacré pour le musulman : son sang, ses biens et son honneur. »"}]},{"id":"N36","num":36,"title":"Soulager le croyant","titleAr":"","takeaway":"Aide les autres : Allah t’aidera. Cherche la science : c’est un chemin vers le Paradis.","source":"Rapporté par Muslim avec ces termes.","units":[{"id":"N36","ar":"عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ عَنْ النَّبِيِّ ﷺ قَالَ: «مَنْ نَفَّسَ عَنْ مُؤْمِنٍ كُرْبَةً مِنْ كُرَبِ الدُّنْيَا نَفَّسَ اللَّهُ عَنْهُ كُرْبَةً مِنْ كُرَبِ يَوْمِ الْقِيَامَةِ، وَمَنْ يَسَّرَ عَلَى مُعْسِرٍ، يَسَّرَ اللَّهُ عَلَيْهِ فِي الدُّنْيَا وَالْآخِرَةِ، وَمَنْ سَتَرَ مُسْلِما سَتَرَهُ اللهُ فِي الدُّنْيَا وَالْآخِرَةِ، وَاَللَّهُ فِي عَوْنِ الْعَبْدِ مَا كَانَ الْعَبْدُ فِي عَوْنِ أَخِيهِ، وَمَنْ سَلَكَ طَرِيقًا يَلْتَمِسُ فِيهِ عِلْمًا سَهَّلَ اللَّهُ لَهُ بِهِ طَرِيقًا إلَى الْجَنَّةِ، وَمَا اجْتَمَعَ قَوْمٌ فِي بَيْتٍ مِنْ بُيُوتِ اللَّهِ يَتْلُونَ كِتَابَ اللَّهِ، وَيَتَدَارَسُونَهُ فِيمَا بَيْنَهُمْ؛ إلَّا نَزَلَتْ عَلَيْهِمْ السَّكِينَةُ، وَغَشِيَتْهُمْ الرَّحْمَةُ، وَ حَفَّتهُمُ المَلاَئِكَة، وَذَكَرَهُمْ اللَّهُ فِيمَنْ عِنْدَهُ، وَمَنْ أَبَطْأَ بِهِ عَمَلُهُ لَمْ يُسْرِعْ بِهِ نَسَبُهُ». بهذا اللفظ.","fr":"D’après Abû Hurayra (qu’Allah l’agrée), d’après le Prophète ﷺ : « Celui qui soulage un croyant d’une détresse de ce monde, Allah le soulagera d’une détresse du Jour de la Résurrection. Celui qui facilite les choses à quelqu’un en difficulté, Allah lui facilitera les choses dans ce monde et dans l’au-delà. Celui qui couvre (les fautes d’)un musulman, Allah le couvrira dans ce monde et dans l’au-delà. Allah aide le serviteur tant que le serviteur aide son frère. Celui qui emprunte un chemin pour y chercher une science, Allah lui facilite par là un chemin vers le Paradis. Des gens ne se réunissent pas dans l’une des maisons d’Allah pour réciter le Livre d’Allah et l’étudier ensemble sans que la sérénité ne descende sur eux, que la miséricorde ne les couvre, que les anges ne les entourent et qu’Allah ne les mentionne auprès de ceux qui sont auprès de Lui. Et celui que ses œuvres ont retardé, sa lignée ne le fera pas avancer. »"}]},{"id":"N37","num":37,"title":"La générosité d’Allah dans l’inscription des actes","titleAr":"","takeaway":"Une bonne intention est déjà récompensée ; une mauvaise action ne compte qu’une fois.","source":"Rapporté par al-Bukhârî et Muslim dans leurs Sahîh avec ces termes.","units":[{"id":"N37","ar":"عَنْ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا عَنْ رَسُولِ اللَّهِ ﷺ فِيمَا يَرْوِيهِ عَنْ رَبِّهِ تَبَارَكَ وَتَعَالَى، قَالَ: «إنَّ اللَّهَ كَتَبَ الْحَسَنَاتِ وَالسَّيِّئَاتِ، ثُمَّ بَيَّنَ ذَلِكَ، فَمَنْ هَمَّ بِحَسَنَةٍ فَلَمْ يَعْمَلْهَا كَتَبَهَا اللَّهُ عِنْدَهُ حَسَنَةً كَامِلَةً، وَإِنْ هَمَّ بِهَا فَعَمِلَهَا كَتَبَهَا اللَّهُ عِنْدَهُ عَشْرَ حَسَنَاتٍ إلَى سَبْعِمِائَةِ ضِعْفٍ إلَى أَضْعَافٍ كَثِيرَةٍ، وَإِنْ هَمَّ بِسَيِّئَةٍ فَلَمْ يَعْمَلْهَا كَتَبَهَا اللَّهُ عِنْدَهُ حَسَنَةً كَامِلَةً، وَإِنْ هَمَّ بِهَا فَعَمِلَهَا كَتَبَهَا اللَّهُ سَيِّئَةً وَاحِدَةً».،، في «صحيحيهما» بهذه الحروف.","fr":"D’après Ibn ‘Abbâs (qu’Allah les agrée), d’après le Messager d’Allah ﷺ, dans ce qu’il rapporte de son Seigneur, Béni et Très-Haut : « Allah a inscrit les bonnes et les mauvaises actions, puis Il l’a expliqué : celui qui projette une bonne action mais ne la fait pas, Allah la lui inscrit auprès de Lui comme une bonne action complète ; s’il la projette et la fait, Allah la lui inscrit comme dix bonnes actions, jusqu’à sept cents fois, et bien plus encore. S’il projette une mauvaise action et ne la fait pas, Allah la lui inscrit comme une bonne action complète ; et s’il la projette et la fait, Allah la lui inscrit comme une seule mauvaise action. »"}]},{"id":"N38","num":38,"title":"L’amour d’Allah pour Ses rapprochés","titleAr":"","takeaway":"On se rapproche d’Allah par les obligations, puis par les actes surérogatoires.","source":"Rapporté par al-Bukhârî.","units":[{"id":"N38","ar":"عَنْ أَبِي هُرَيْرَة رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُول اللَّهِ ﷺ إنَّ اللَّهَ تَعَالَى قَالَ: «مَنْ عَادَى لِي وَلِيًّا فَقْد آذَنْتهُ بِالْحَرْبِ، وَمَا تَقَرَّبَ إلَيَّ عَبْدِي بِشَيْءٍ أَحَبَّ إلَيَّ مِمَّا افْتَرَضْتُهُ عَلَيْهِ، وَلَا يَزَالُ عَبْدِي يَتَقَرَّبُ إلَيَّ بِالنَّوَافِلِ حَتَّى أُحِبَّهُ، فَإِذَا أَحْبَبْتُهُ كُنْت سَمْعَهُ الَّذِي يَسْمَعُ بِهِ، وَبَصَرَهُ الَّذِي يُبْصِرُ بِهِ، وَيَدَهُ الَّتِي يَبْطِشُ بِهَا، وَرِجْلَهُ الَّتِي يَمْشِي بِهَا، وَلَئِنْ سَأَلَنِي لَأُعْطِيَنَّهُ، وَلَئِنْ اسْتَعَاذَنِي لَأُعِيذَنَّهُ».","fr":"D’après Abû Hurayra (qu’Allah l’agrée), qui a dit : Le Messager d’Allah ﷺ a dit : « Allah le Très-Haut a dit : “Celui qui est hostile à l’un de Mes rapprochés (walî), Je lui déclare la guerre. Mon serviteur ne se rapproche pas de Moi par une chose que J’aime davantage que ce que Je lui ai imposé, et Mon serviteur ne cesse de se rapprocher de Moi par les œuvres surérogatoires jusqu’à ce que Je l’aime. Lorsque Je l’aime, Je suis son ouïe par laquelle il entend, sa vue par laquelle il voit, sa main avec laquelle il saisit et son pied avec lequel il marche. S’il Me demande, Je lui donne assurément ; et s’il cherche refuge auprès de Moi, Je le protège assurément.” »"}]},{"id":"N39","num":39,"title":"L’erreur, l’oubli et la contrainte sont pardonnés","titleAr":"","takeaway":"Allah ne tient pas rigueur de ce qui est fait sans le vouloir.","source":"Hadith bon, rapporté par Ibn Mâja, al-Bayhaqî et d’autres.","units":[{"id":"N39","ar":"عَنْ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «إنَّ اللَّهَ تَجَاوَزَ لِي عَنْ أُمَّتِي الْخَطَأَ وَالنِّسْيَانَ وَمَا اسْتُكْرِهُوا عَلَيْهِ». حَدِيثٌ حَسَنٌ، رَوَاهُ ابْنُ مَاجَهْ.","fr":"D’après Ibn ‘Abbâs (qu’Allah les agrée) : Le Messager d’Allah ﷺ a dit : « Allah a pardonné à ma communauté l’erreur, l’oubli et ce à quoi elle a été contrainte. »"}]},{"id":"N40","num":40,"title":"Sois dans ce monde comme un étranger","titleAr":"","takeaway":"Profite de ta santé et de ta vie avant qu’elles ne passent.","source":"Rapporté par al-Bukhârî.","units":[{"id":"N40","ar":"عَنْ ابْن عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أَخَذَ رَسُولُ اللَّهِ ﷺ بِمَنْكِبِي، وَقَالَ: «كُنْ فِي الدُّنْيَا كَأَنَّك غَرِيبٌ أَوْ عَابِرُ سَبِيلٍ». وَكَانَ ابْنُ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا يَقُولُ: إذَا أَمْسَيْتَ فَلَا تَنْتَظِرْ الصَّبَاحَ، وَإِذَا أَصْبَحْتَ فَلَا تَنْتَظِرْ الْمَسَاءَ، وَخُذْ مِنْ صِحَّتِك لِمَرَضِك، وَمِنْ حَيَاتِك لِمَوْتِك.","fr":"D’après Ibn ‘Umar (qu’Allah les agrée), qui a dit : Le Messager d’Allah ﷺ me prit par l’épaule et dit : « Sois dans ce monde comme si tu étais un étranger ou un voyageur de passage. » Ibn ‘Umar disait : « Le soir, n’attends pas le matin ; le matin, n’attends pas le soir. Prends de ta santé pour ta maladie, et de ta vie pour ta mort. »"}]},{"id":"N41","num":41,"title":"Suivre ce qu’a apporté le Prophète","titleAr":"","takeaway":"La foi complète, c’est aimer ce qu’a apporté le Prophète ﷺ.","source":"Hadith bon et authentique, rapporté dans le livre « al-Hujja » avec une chaîne authentique.","units":[{"id":"N41","ar":"عَنْ أَبِي مُحَمَّدٍ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللَّهُ عَنْهُمَا، قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ «لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى يَكُونَ هَوَاهُ تَبَعًا لِمَا جِئْتُ بِهِ». حَدِيثٌ حَسَنٌ صَحِيحٌ، رَوَيْنَاهُ فِي كِتَابِ «الْحُجَّةِ» بِإِسْنَادٍ صَحِيحٍ.","fr":"D’après Abû Muhammad ‘Abd Allâh ibn ‘Amr ibn al-‘Âs (qu’Allah les agrée), qui a dit : Le Messager d’Allah ﷺ a dit : « Aucun de vous n’a vraiment la foi tant que ses désirs ne suivent pas ce que j’ai apporté. »"}]},{"id":"N42","num":42,"title":"L’immensité du pardon d’Allah","titleAr":"","takeaway":"Ne désespère jamais : invoque Allah, demande-Lui pardon, ne Lui associe rien.","source":"Rapporté par at-Tirmidhî, qui a dit : hadith bon et authentique.","units":[{"id":"N42","ar":"عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْت رَسُولَ اللَّهِ ﷺ يَقُولُ: قَالَ اللَّهُ تَعَالَى: «يَا ابْنَ آدَمَ! إِنَّكَ مَا دَعَوْتنِي وَرَجَوْتنِي غَفَرْتُ لَك عَلَى مَا كَانَ مِنْك وَلَا أُبَالِي، يَا ابْنَ آدَمَ! لَوْ بَلَغَتْ ذُنُوبُك عَنَانَ السَّمَاءِ ثُمَّ اسْتَغْفَرْتنِي غَفَرْتُ لَك، يَا ابْنَ آدَمَ! إنَّك لَوْ أتَيْتنِي بِقُرَابِ الْأَرْضِ خَطَايَا ثُمَّ لَقِيتنِي لَا تُشْرِكُ بِي شَيْئًا لَأَتَيْتُك بِقُرَابِهَا مَغْفِرَةً». رَوَاهُ التِّرْمِذِيُّ، وَقَالَ: حَدِيثٌ حَسَنٌ صَحِيحٌ.","fr":"D’après Anas ibn Mâlik (qu’Allah l’agrée), qui a dit : J’ai entendu le Messager d’Allah ﷺ dire : « Allah le Très-Haut a dit : “Ô fils d’Adam ! Tant que tu M’invoques et que tu espères en Moi, Je te pardonne ce que tu as fait, sans M’en soucier. Ô fils d’Adam ! Si tes péchés atteignaient les nuages du ciel, puis que tu Me demandais pardon, Je te pardonnerais. Ô fils d’Adam ! Si tu venais à Moi avec presque la terre entière de fautes, puis que tu Me rencontrais sans rien M’associer, Je viendrais à toi avec presque autant de pardon.” »"}]}]};
